import 'package:flutter/material.dart';
import '../data/dummy_data.dart';
class ClubsScreen extends StatefulWidget { const ClubsScreen({super.key}); @override State<ClubsScreen> createState() => _ClubsScreenState(); }
class _ClubsScreenState extends State<ClubsScreen> { String query=''; @override Widget build(BuildContext context) { final list=clubs.where((c)=>c.name.toLowerCase().contains(query.toLowerCase())||c.category.toLowerCase().contains(query.toLowerCase())).toList(); return Scaffold(appBar: AppBar(title: const Text('Clubs')), body: Column(children: [Padding(padding: const EdgeInsets.all(16), child: TextField(onChanged:(v)=>setState(()=>query=v), decoration: const InputDecoration(hintText:'Search clubs', prefixIcon:Icon(Icons.search), border:OutlineInputBorder()))), Expanded(child: ListView.builder(padding: const EdgeInsets.symmetric(horizontal:16), itemCount:list.length, itemBuilder:(_,i){final c=list[i]; return Card(margin:const EdgeInsets.only(bottom:10), child: ListTile(leading:const CircleAvatar(child:Icon(Icons.groups)), title:Text(c.name,style:const TextStyle(fontWeight:FontWeight.bold)), subtitle:Text('${c.category}\n${c.description}'), isThreeLine:true, trailing:TextButton(onPressed:()=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Joined ${c.name}'))), child:const Text('Join'))));}))])); } }
